const s={0:"⁰",1:"¹",2:"²",3:"³",4:"⁴",5:"⁵",6:"⁶",7:"⁷",8:"⁸",9:"⁹"};function f(i){const t=Number(i);if(!Number.isFinite(t))return"0";if(Math.abs(t)<1e8)return t.toLocaleString("en-US");let e=Math.floor(Math.log10(Math.abs(t))),n=(t/10**e).toFixed(2);Number(n)>=10&&(e+=1,n=(t/10**e).toFixed(2));const o=n.replace(/\.?0+$/,""),a=String(e).split("").map(r=>s[r]||r).join("");return o+"×10"+a}export{f};
